-- -----------------------------------------------------------------------------
-- Lookups: types (case-insensitive de-dupe against existing)
-- -----------------------------------------------------------------------------
INSERT INTO incident_types (id, name)
SELECT gen_random_uuid(), x.name
FROM (
  SELECT DISTINCT upper(btrim(type_name)) AS name
  FROM _hist_import
  WHERE btrim(coalesce(type_name, '')) <> ''
) x
WHERE NOT EXISTS (
  SELECT 1 FROM incident_types t WHERE upper(t.name) = x.name
);

-- Actions (preserve useful casing from sheet; skip empty / noise-only if already exists)
INSERT INTO incident_actions (id, name)
SELECT gen_random_uuid(), x.name
FROM (
  SELECT DISTINCT upper(btrim(action_name)) AS name
  FROM _hist_import
  WHERE btrim(coalesce(action_name, '')) <> ''
) x
WHERE NOT EXISTS (
  SELECT 1 FROM incident_actions a WHERE upper(a.name) = x.name
);

-- Team leaders
INSERT INTO team_leaders (id, name)
SELECT gen_random_uuid(), upper(btrim(x.name))
FROM (
  SELECT DISTINCT btrim(team_leader) AS name
  FROM _hist_import
  WHERE btrim(coalesce(team_leader, '')) <> ''
) x
WHERE NOT EXISTS (
  SELECT 1 FROM team_leaders tl WHERE lower(tl.name) = lower(x.name)
);

-- Drivers (username unique, uppercase)
INSERT INTO drivers (id, name, username)
SELECT gen_random_uuid(), upper(btrim(x.username)), upper(btrim(x.username))
FROM (
  SELECT DISTINCT btrim(driver_username) AS username
  FROM _hist_import
  WHERE btrim(coalesce(driver_username, '')) <> ''
) x
WHERE NOT EXISTS (
  SELECT 1 FROM drivers d WHERE upper(d.username) = upper(x.username)
);

-- Responded By free-text names (optional lookup)
INSERT INTO responded_by (id, name)
SELECT gen_random_uuid(), btrim(x.name)
FROM (
  SELECT DISTINCT btrim(response) AS name
  FROM _hist_import
  WHERE btrim(coalesce(response, '')) <> ''
) x
WHERE NOT EXISTS (
  SELECT 1 FROM responded_by rb WHERE lower(rb.name) = lower(x.name)
);

-- -----------------------------------------------------------------------------
-- Insert incidents (skip existing non-blank reference numbers)
-- -----------------------------------------------------------------------------
INSERT INTO incidents (
  id,
  reference_no,
  date_received,
  time,
  email_received_time,
  type_id,
  driver_id,
  team_leader_id,
  response,
  reference_text,
  action_id,
  date_response,
  time_response,
  email_sender,
  email_subject,
  location_street,
  location_suburb,
  sender,
  marked,
  source,
  status,
  duplicate_exempt,
  updated_at
)
SELECT
  gen_random_uuid(),
  coalesce(h.reference_no, ''),
  h.date_received,
  coalesce(h.time_received, ''),
  nullif(h.time_received, ''),
  (
    SELECT t.id FROM incident_types t
    WHERE upper(t.name) = upper(btrim(h.type_name))
    LIMIT 1
  ),
  (
    SELECT d.id FROM drivers d
    WHERE upper(d.username) = upper(btrim(h.driver_username))
    LIMIT 1
  ),
  (
    SELECT tl.id FROM team_leaders tl
    WHERE lower(tl.name) = lower(btrim(h.team_leader))
    LIMIT 1
  ),
  coalesce(h.response, ''),
  coalesce(h.reference_text, ''),
  (
    SELECT a.id FROM incident_actions a
    WHERE upper(a.name) = upper(btrim(h.action_name))
    LIMIT 1
  ),
  h.date_response,
  nullif(h.time_response, ''),
  NULL,  -- email_sender (historical sheet has no email)
  NULL,  -- email_subject
  '',
  '',
  coalesce(h.sender, ''),
  coalesce(h.marked, ''),
  'import',
  'Open',
  false,
  now()
FROM _hist_import h
WHERE
  -- skip blank garbage
  (
    btrim(coalesce(h.type_name, '')) <> ''
    OR btrim(coalesce(h.reference_no, '')) <> ''
    OR btrim(coalesce(h.reference_text, '')) <> ''
  )
  AND NOT (
    -- re-run safety: skip when this reference already exists
    btrim(coalesce(h.reference_no, '')) <> ''
    AND EXISTS (
      SELECT 1 FROM incidents i
      WHERE btrim(coalesce(i.reference_no, '')) = btrim(h.reference_no)
    )
  );

-- Summary
SELECT
  (SELECT count(*) FROM _hist_import) AS staged_rows,
  (SELECT count(*) FROM incidents WHERE source = 'import' AND date_received < DATE '2026-07-01') AS import_rows_before_jul2026,
  (SELECT count(*) FROM incidents WHERE date_received >= DATE '2026-07-01') AS rows_jul2026_or_later_untouched,
  (SELECT min(date_received) FROM incidents WHERE source = 'import') AS min_import_date,
  (SELECT max(date_received) FROM incidents WHERE source = 'import' AND date_received < DATE '2026-07-01') AS max_import_date_in_scope;

COMMIT;
